INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('401c32f6-520d-4c56-9339-0e50b6451b29', 'islamic_living', 'Mengaji Metode Ummi', 'Membaca Al-Qur''an Metode Ummi (Jilid 1–6)', 'Metode Ummi: mudah, menyenangkan, menyentuh hati. Anak membaca langsung tanpa mengeja, dengan tartil sejak awal, bertahap dari Jilid 1 sampai Jilid 6 lalu berlanjut ke Al-Qur''an. Guide menyimak satu per satu dalam talaqqi harian; satu halaman lancar bila dibaca benar dan lancar sesuai tahapnya; naik jilid disahkan lewat munaqosyah sesuai standar Ummi. Yang dicatat: jilid dan halaman berjalan, bunyi/hukum bacaan yang masih dibimbing, kelancaran tartil. Kecepatan anak tidak pernah dibandingkan.', NULL, 1, TRUE);
