INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('5734cc02-6779-4a08-b7ab-4519e177135a', 'islamic_living', 'Huruf Hijaiyah', 'Huruf ha', 'Urutan ke-26 mengikuti urutan buku Ummi Jilid 1. Diperkenalkan lewat banyak indra: mendengar bunyi dari guide, melihat kartu besar, meraba kartu huruf bertekstur, menelusuri di nampan pasir, membentuk dari bahan.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('8b006ff2-9ffe-49e7-abf1-b18718f83a1e', 'bahasa_arab', 'Bahan Dasar', 'Salam & Kata Sopan', 'Isi: Assalamu''alaikum (السلام عليكم), Shabahul khair (صباح الخير, selamat pagi), Syukran (شكرا, terima kasih), ''Afwan (عفوا, sama-sama), Ma''as-salamah (مع السلامة, sampai jumpa), Ahlan wa sahlan (أهلا وسهلا, selamat datang)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('0e90aacb-04e0-4d9b-8bc2-90d12fd0a3fa', 'bahasa_arab', 'Bahan Dasar', 'Warna', 'Isi: Ahmar (أحمر, merah), Azraq (أزرق, biru), Akhdhar (أخضر, hijau), Ashfar (أصفر, kuning), Abyadh (أبيض, putih), Aswad (أسود, hitam)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('424e5be0-be1b-4ae3-a094-6e78fe12594d', 'bahasa_arab', 'Bahan Dasar', 'Angka 1-10', 'Isi: Wahid (واحد, satu), Itsnain (اثنان, dua), Tsalatsah (ثلاثة, tiga), Arba''ah (أربعة, empat), Khamsah (خمسة, lima), Sittah (ستة, enam), Sab''ah (سبعة, tujuh), Tsamaniyah (ثمانية, delapan), Tis''ah (تسعة, sembilan), ''Asyarah (عشرة, sepuluh)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('47250ccc-99d8-40b3-8cd0-84ceddd6140d', 'bahasa_arab', 'Bahan Dasar', 'Hewan', 'Isi: Qiththah (قطة, kucing), Kalb (كلب, anjing), Tha''ir (طائر, burung), Samakah (سمكة, ikan), Baqarah (بقرة, sapi), Hishan (حصان, kuda), Jamal (جمل, unta), Asad (أسد, singa)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('114ec4e5-0505-45b3-9a89-d724a084645b', 'bahasa_arab', 'Bahan Dasar', 'Tubuhku', 'Isi: Ra''s (رأس, kepala), ''Ain (عين, mata), Yad (يد, tangan), Rijl (رجل, kaki), Fam (فم, mulut), Anf (أنف, hidung)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('d8659a92-1d17-40b4-8eca-25d2b1678197', 'bahasa_arab', 'Bahan Dasar', 'Keluargaku', 'Isi: Ab (أب, ayah), Umm (أم, ibu), Akh (أخ, kakak laki-laki), Ukht (أخت, kakak perempuan), Jadd (جد, kakek), Jaddah (جدة, nenek)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('2bfc98e9-a0cb-4ad1-86aa-5013ebbdbf5f', 'bahasa_arab', 'Bahan Dasar', 'Makanan & Minuman', 'Isi: Khubz (خبز, roti), Ma'' (ماء, air), Halib (حليب, susu), Tuffah (تفاح, apel), Mauz (موز, pisang), Urz (أرز, nasi)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('d2f07b80-82d6-43ba-aecb-3418bda1c0cb', 'bahasa_arab', 'Bahan Dasar', 'Alam di Sekitarku', 'Isi: Syams (شمس, matahari), Qamar (قمر, bulan), Najm (نجم, bintang), Syajarah (شجرة, pohon), Zahr (زهر, bunga), Bahr (بحر, laut), Mathar (مطر, hujan)
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('03b0e73c-4161-4027-bade-98eb764ebb0c', 'bahasa_arab', 'Bahan Dasar', 'Dialog Perkenalan', 'Isi: Assalamu''alaikum. Ma ismuk? (ما اسمك, siapa namamu) - Ismi ... (اسمي, namaku). Kaifa haluk? (كيف حالك, bagaimana kabarmu) - Ana bikhair, alhamdulillah (أنا بخير الحمد لله, aku baik, alhamdulillah). Dikenalkan lewat bermain peran berpasangan pada circle time untuk CASA Tahun 2 dan 3.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('ab2d6d4d-efe2-47af-a7a1-ac1c1369c72c', 'bahasa_arab', 'Bahan Dasar', 'Ungkapan Momen Harian', 'Isi: Bismillah sebelum memulai dan makan, Alhamdulillah sesudahnya, Insya Allah untuk rencana, Masya Allah untuk kekaguman, Astaghfirullah saat berlatih memperbaiki kesalahan, Jazakumullah khairan untuk terima kasih yang lebih dalam. Ungkapan ini tidak diajarkan sebagai daftar, melainkan diucapkan dewasa pada momen aslinya sampai anak memakainya sendiri.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('8551da0f-cf8f-44d3-b158-ec6631dd7bdd', 'bahasa_arab', 'Bahan Dasar', 'Pembuka Percakapan Circle Time', 'Isi: Satu pertanyaan bergiliran dalam Bahasa Arab sederhana, misalnya Ma al-lawn? (ما اللون, warna apa ini) sambil menunjukkan benda, dijawab anak dengan satu kata Arab. Melatih keberanian mengucapkan dan kosakata warna serta benda.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('bdd5f9b9-49fa-4cfa-9c15-2caf6639d019', 'bahasa_arab', 'Tangga Menulis Hijaiyah', 'Tahap 1 — Meraba Huruf', 'Kegiatan anak: Anak meraba kartu huruf hijaiyah bertekstur sambil mendengar dan menyebut bunyinya, sejajar huruf sandpaper.', NULL, 1, TRUE);
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('c31a70ec-59dd-4449-b0c2-3cbe33c0007b', 'bahasa_arab', 'Tangga Menulis Hijaiyah', 'Tahap 2 — Menelusuri dengan Jari', 'Kegiatan anak: Anak menelusuri bentuk huruf dengan jari di atas media bertekstur dan nampan pasir, membangun ingatan gerak bentuk huruf.', NULL, 2, TRUE);
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('82949625-1726-4be7-854d-5aaa32967343', 'bahasa_arab', 'Tangga Menulis Hijaiyah', 'Tahap 3 — Menelusuri dengan Alat', 'Kegiatan anak: Anak menelusuri huruf dengan stik dan kemudian alat tulis pada papan kecil dan kertas besar tanpa garis, fokus pada arah dan urutan goresan.', NULL, 3, TRUE);
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('75751d49-f9d4-4ece-a80b-09b2cc759904', 'bahasa_arab', 'Tangga Menulis Hijaiyah', 'Tahap 4 — Menulis Huruf Lepas', 'Kegiatan anak: Anak menulis huruf yang sudah dikenalnya pada garis bantu, satu huruf pada satu waktu, dari huruf yang paling ia kuasai bacaannya.', NULL, 4, TRUE);
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('f286619a-b169-40f0-9ada-e1e371967705', 'bahasa_arab', 'Tangga Menulis Hijaiyah', 'Tahap 5 — Menulis Huruf Bersambung', 'Kegiatan anak: Untuk CASA Tahun 3 yang siap: anak mengenal bentuk huruf di awal, tengah, dan akhir kata, lalu menulis kata pendek yang sangat dikenalnya, misalnya kata dari surah pendeknya.', NULL, 5, TRUE);
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('9c50a19d-e5e0-472a-b996-3b6529facf94', 'bahasa_inggris', 'Dialog Situasi', 'Menamai Perasaan', 'Dialog: Guru/Orang tua: How do you feel today? - Anak: I am happy. / I am sad. / I am tired. - Dewasa: It is okay to feel sad. Do you want a hug? - Anak: Yes, please. / No, thank you.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('df9a6078-fbef-4033-9680-8decfc647fbd', 'bahasa_inggris', 'Dialog Situasi', 'Ke Dokter', 'Dialog: Dewasa: Where does it hurt? - Anak: My tummy hurts. / My head hurts. - Dewasa: Let us tell the doctor. Open your mouth, please. Say aaa. - Anak: Aaa. Thank you, Doctor.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('3c7bfd93-cfce-41f4-91bc-50f3538965ad', 'bahasa_inggris', 'Dialog Situasi', 'Di Pasar & Warung', 'Dialog: Anak: Good morning. I want bananas, please. - Penjual/Dewasa: How many? - Anak: Three, please. - Dewasa: Here you are. - Anak: Thank you. How much is it?
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('77c4b24d-e97e-41d2-9a29-5bcfc929b890', 'bahasa_inggris', 'Dialog Situasi', 'Di Taman Bermain', 'Dialog: Anak: Let us play on the slide. - Teman: Okay. Your turn. / My turn. - Anak: Push me, please. Higher! - Teman: Be careful. Hold on tight.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('04bde7a9-3e9f-4851-83a8-29f6b4494938', 'bahasa_inggris', 'Dialog Situasi', 'Membantu di Dapur', 'Dialog: Dewasa: Can you help me, please? - Anak: Yes, I can. What can I do? - Dewasa: Wash the apples, please. Put them here. - Anak: All done. It looks yummy.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('068fb4e9-2500-433f-8085-b5a481a336d7', 'bahasa_inggris', 'Dialog Situasi', 'Di Pantai & Alam', 'Dialog: Anak: Look, a crab. It is small. - Dewasa: The water is cold. Let us build a sand castle. - Anak: I found a shell. It is beautiful.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('7157298c-baea-44b9-8484-b42c3f004d4b', 'bahasa_inggris', 'Dialog Situasi', 'Di Kebun Binatang', 'Dialog: Anak: Look at the elephant. It is big. - Dewasa: What does the monkey eat? - Anak: It eats bananas. The lion says roar.
INSERT INTO bahan_ajar (id, kategori, subkategori, judul, isi, teks_latin, urutan, aktif) VALUES ('0b005e0a-6fe4-4211-a46d-3d82e62f925a', 'bahasa_inggris', 'Dialog Situasi', 'Hari Hujan di Rumah', 'Dialog: Anak: It is raining. I hear thunder. - Dewasa: Let us stay inside. Do you want hot chocolate? - Anak: Yes, please. Let us read a story.
INSERT INTO calistung_tahap (id, nama, keterangan, urutan, aktif) VALUES ('aa8f997d-9d9b-45f5-a425-a7e25463d940', 'Membaca — Fondasi', 'Untaian Membaca, tahap Fondasi. Tahap dinyatakan selesai bila seluruh indikator tahap itu teramati konsisten pada sekurang-kurangnya tiga sesi berbeda dengan tingkat bantuan mandiri (Program Khusus Calistung, Bagian 3). Sesi 60 menit, individual atau kelompok sangat kecil maks. 4 anak, dua kali sepekan, sesudah pukul 13.00.', 1, TRUE);
