INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('8e64b193-e094-4cd0-aa4a-beea52c2ec44', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Anak mengenal nilai tempat secara konkret lewat manik emas (satuan, puluhan, ratusan) sebagai pengalaman, bukan hafalan', 'Indikator tahap — Program Khusus Calistung Pendekatan Montessori ZKC, Bagian 2.', 5, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('e2f706b6-adaf-4506-bf3a-4a6ae6336811', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Anak menjumlah dan mengurang dengan benda dan manik secara konkret, lalu mencatatnya dengan simbol', 'Indikator tahap — Program Khusus Calistung Pendekatan Montessori ZKC, Bagian 2.', 1, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('5d03733f-8380-43f5-9d4b-3c7449e542b5', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Anak memahami membagi rata sebagai asal pembagian', 'Indikator tahap — Program Khusus Calistung Pendekatan Montessori ZKC, Bagian 2.', 2, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('fd555c47-bce6-4ecf-afe8-6387a51a9f84', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Anak mengukur dan membandingkan panjang, berat, dan isi dengan alat sederhana', 'Indikator tahap — Program Khusus Calistung Pendekatan Montessori ZKC, Bagian 2.', 3, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('c91220bd-4150-42fc-988c-a28a92c6b5a5', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Anak membaca soal cerita sederhana dan memilih cara menyelesaikannya dengan benda', 'Indikator tahap — Program Khusus Calistung Pendekatan Montessori ZKC, Bagian 2.', 4, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('b9588a27-73b7-405c-b32d-e9f5a4c15da1', 'aa8f997d-9d9b-45f5-a425-a7e25463d940', 'Membaca Tahap 0 — Bahasa Lisan & Permainan Bunyi', 'Fokus: Kesadaran bunyi awal, tengah, akhir kata dan kekayaan kosakata lisan. Aparatus utama: Permainan bunyi I Spy, kartu klasifikasi dan kosakata, buku read aloud. Tanda siap masuk: Tahap awal semua anak; anak menikmati dibacakan dan berbicara kalimat sederhana. Tanda siap lanjut: Anak memecah kata pendek menjadi bunyi-bunyinya secara konsisten dan mulai berminat pada huruf. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 100, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('649e4de7-fb46-43f1-974b-8627dc3f2abb', 'e83d932f-3c44-4abf-8acd-8e910d4648d5', 'Membaca Tahap 1 — Huruf Raba (Sandpaper Letters)', 'Fokus: Mengikat bunyi, bentuk, dan gerakan menulis huruf. Aparatus utama: Sandpaper Letters (huruf raba). Tanda siap masuk: Lulus Tahap 0; jari terlatih lewat kegiatan sensorial; minat huruf muncul. Tanda siap lanjut: Anak mengenal bunyi 8 sampai 10 huruf secara acak lintas sesi dan mulai menggabungkan dua bunyi. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 101, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('f239ccab-c672-4aa3-a065-438270bedcde', 'e83d932f-3c44-4abf-8acd-8e910d4648d5', 'Membaca Tahap 2 — LMA (Large Movable Alphabet)', 'Fokus: Menyusun kata dari bunyi yang didengar (encoding). Aparatus utama: Large Movable Alphabet (huruf lepas besar), benda dan gambar kecil. Tanda siap masuk: Anak mengenal bunyi huruf dasar dan memecah kata menjadi bunyi. Tanda siap lanjut: Anak menyusun kata berpola sederhana secara mandiri dan membaca kembali susunannya. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 102, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('6b9853e2-196d-4052-810d-9386bc30c208', 'e83d932f-3c44-4abf-8acd-8e910d4648d5', 'Membaca Tahap 3 — CMA (Cursive Movable Alphabet)', 'Fokus: Jembatan dari huruf cetak menuju huruf sambung. Aparatus utama: Cursive Movable Alphabet (huruf lepas sambung), kartu pasangan cetak dan sambung. Tanda siap masuk: Anak mantap menyusun dan membaca dengan LMA cetak; minat pada tulisan sambung. Tanda siap lanjut: Anak membaca dan menyusun kata sederhana dalam huruf sambung dengan bantuan minimal. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 103, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('b4d2b6d3-6657-4560-8762-3c0aec139eac', 'e83d932f-3c44-4abf-8acd-8e910d4648d5', 'Membaca Tahap 4A — Seri Pink', 'Fokus: Membaca kata, kalimat, dan buku berjenjang berpola teratur. Aparatus utama: Kartu kata, kartu kalimat, dan buku berjenjang Seri Pink. Tanda siap masuk: Anak mantap di LMA dan mengenal seluruh bunyi huruf dasar. Tanda siap lanjut: Anak membaca kata dan kalimat Seri Pink secara mandiri dengan pemahaman. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 104, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('0db3dbab-c592-4ac9-83fe-465fbce00256', '1ec45381-6e23-484d-a125-31752bbd6eda', 'Membaca Tahap 4B — Seri Biru', 'Fokus: Digraf (ng, ny, kh, sy) dan pola lebih panjang. Aparatus utama: Kartu kata, kartu kalimat, dan buku berjenjang Seri Biru. Tanda siap masuk: Anak menyelesaikan Seri Pink dengan pemahaman. Tanda siap lanjut: Anak membaca teks Seri Biru dengan lancar dan mulai memprediksi kata dari konteks. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 105, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('41c88f1f-baf6-4f3f-a4de-bd0f59ca3f5b', '1ec45381-6e23-484d-a125-31752bbd6eda', 'Membaca Tahap 4C — Seri Hijau', 'Fokus: Fonogram dan kata tidak beraturan. Aparatus utama: Kartu kata dan buku berjenjang Seri Hijau. Tanda siap masuk: Anak membaca Seri Biru dengan lancar; kosakata lisan cukup kaya. Tanda siap lanjut: Anak membaca cerita pendek Seri Hijau secara mandiri dan mengenali fonogram tanpa mengeja. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 106, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('801921d8-1c04-4202-a323-155a53b14e13', '1ec45381-6e23-484d-a125-31752bbd6eda', 'Membaca Tahap 5 — Puzzle Words & Definisi', 'Fokus: Kata yang dikenali seketika dan pemahaman makna kata. Aparatus utama: Kartu puzzle words, kartu definisi dan kartu kontrol bergambar. Tanda siap masuk: Anak membaca Seri Biru dan Hijau; mulai membaca untuk makna. Tanda siap lanjut: Anak mengenali kata tahap ini seketika di dalam kalimat dan menjelaskan maknanya. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 107, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('cc914a36-a133-407b-aa09-321bf9584221', '1ec45381-6e23-484d-a125-31752bbd6eda', 'Membaca Tahap 6 — Membaca Menyeluruh', 'Fokus: Membaca buku nyata, memahami isi, mengenal fungsi kata. Aparatus utama: Buku nyata beragam topik, kartu perintah, label dan kartu fungsi kata. Tanda siap masuk: Anak membaca cerita pendek secara mandiri dan memilih buku atas minatnya. Tanda siap lanjut: Posisi Penerapan penuh; anak beralih ke pemeliharaan lewat membaca mandiri. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 108, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('bfceeabb-603b-47a4-b91d-2cda9a0c62bc', '9173d74c-f586-4d5f-952a-9a7a182f1439', 'Menulis — Persiapan Tidak Langsung', 'Fokus: Kekuatan jari, koordinasi mata dan tangan, postur dan arah kerja. Aparatus utama: Kegiatan keterampilan dasar: jepit, tuang, gunting, ronce, telusur bentuk. Tanda siap masuk: Tahap awal semua anak, terutama yang genggamannya belum mantap. Tanda siap lanjut: Anak menggenggam dengan tripod yang berkembang dan bekerja di meja 10 sampai 15 menit. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 109, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('51fa41ce-ac20-4ff3-986a-9a896ef39921', '9173d74c-f586-4d5f-952a-9a7a182f1439', 'Menulis — Metal Insets', 'Fokus: Kontrol alat tulis, tekanan tangan, dan ketelitian garis. Aparatus utama: Metal Insets (sisipan bentuk logam) dan pensil warna. Tanda siap masuk: Persiapan tidak langsung dasar berjalan; minat membuat pola muncul. Tanda siap lanjut: Anak mengisi bentuk dengan garis rapat dan rata serta tekun menyelesaikan satu bentuk. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 110, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('cf1155ab-a21c-45d8-9063-defd50502ec3', '745fd94a-2861-42ca-8b0c-91ab226dc5d1', 'Menulis — Menulis Huruf', 'Fokus: Memindahkan kesan raba huruf menjadi tulisan tangan. Aparatus utama: Huruf raba, papan tulis besar, kertas tanpa garis lalu bergaris besar. Tanda siap masuk: Anak mengenal bunyi huruf itu dan kontrol tangannya siap. Tanda siap lanjut: Anak menulis huruf yang dikenalnya dengan arah benar tanpa contoh. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 111, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('05b83d58-acb1-42a8-993a-16c7c19969ed', '745fd94a-2861-42ca-8b0c-91ab226dc5d1', 'Menulis — Menyusun lalu Menulis', 'Fokus: Memisahkan beban berpikir (menyusun) dari beban tangan (menulis). Aparatus utama: LMA, papan dan buku anak. Tanda siap masuk: Anak aktif menyusun kata dengan LMA dan mulai menulis huruf. Tanda siap lanjut: Anak menulis kata sederhana tanpa menyusun lebih dahulu; ledakan menulis terjadi. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 112, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('cd86b8ef-052b-4825-8932-e8645a05966a', '4d901137-c953-4701-b6a8-ccddbb70281a', 'Menulis — Kata & Kalimat Ciptaan Anak', 'Fokus: Menulis dari dikte bunyi dan dari pikiran sendiri. Aparatus utama: Buku bergaris besar, kartu gambar, jurnal pengalaman anak. Tanda siap masuk: Anak menulis kata tanpa susunan awal; bunyi huruf dasar mantap. Tanda siap lanjut: Anak menulis beberapa kalimat tentang pengalamannya yang terbaca orang lain. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 113, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('97a1ddb4-1a37-4609-9214-b6b27a5b0fd1', '4d901137-c953-4701-b6a8-ccddbb70281a', 'Menulis — Huruf Sambung (CMA, jalur pilihan)', 'Fokus: Menulis huruf sambung bagi anak yang siap dan berminat (jalur pilihan). Aparatus utama: CMA, kartu huruf sambung, buku bergaris besar. Tanda siap masuk: Anak membaca huruf sambung lewat CMA dan menginginkan menulis sambung. Tanda siap lanjut: Anak menulis kata dan kalimat sambung sederhana yang terbaca. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 114, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('7f3201af-1200-4161-aea6-f5bdacde0886', '7cf243b7-5e3b-4c42-9959-cca425297a36', 'Berhitung — Batang Bilangan (Number Rods)', 'Fokus: Kuantitas 1 sampai 10 sebagai panjang yang nyata. Aparatus utama: Number Rods (batang bilangan). Tanda siap masuk: Anak dapat berkonsentrasi pada kegiatan meja dan membawa benda panjang dengan aman. Tanda siap lanjut: Anak menyebutkan jumlah tiap batang tanpa menghitung ulang dan mengurutkan 1 sampai 10. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 115, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('651326f0-7f36-4360-8180-04d44905315f', '7cf243b7-5e3b-4c42-9959-cca425297a36', 'Berhitung — Angka Raba (Sandpaper Numbers)', 'Fokus: Lambang angka 0 sampai 9 beserta arah tulisnya. Aparatus utama: Sandpaper Numbers (angka raba). Tanda siap masuk: Anak mengenal kuantitas angka yang diperkenalkan lewat batang bilangan. Tanda siap lanjut: Anak mengenal lambang 0 sampai 9 secara acak lintas sesi. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 116, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('c3a33dcf-988f-4f00-864f-73a6cb4cdc18', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Berhitung — Batang Bilangan & Kartu Angka', 'Fokus: Mempertemukan kuantitas dan simbol 1 sampai 10. Aparatus utama: Batang bilangan dan kartu angka besar. Tanda siap masuk: Anak mantap pada batang bilangan dan angka raba. Tanda siap lanjut: Anak memasangkan seluruh kuantitas dan simbol 1 sampai 10 tanpa bantuan. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 117, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('67657f6e-8603-4a6d-84fe-3cf5de590c8d', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Berhitung — Kotak Gelondong (Spindle Box)', 'Fokus: Konsep nol dan ketepatan menghitung benda lepas. Aparatus utama: Spindle Box (kotak gelondong) berisi 45 gelondong. Tanda siap masuk: Anak mengenal lambang 0 sampai 9 dan memasangkannya dengan batang. Tanda siap lanjut: Anak menyelesaikan seluruh kompartemen tanpa kesalahan secara mandiri. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 118, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('16d40763-944d-4a33-8738-ea40ccef5c56', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Berhitung — Kartu & Benda Hitung (Cards and Counters)', 'Fokus: Pasangan simbol dan jumlah sampai 10; pola ganjil dan genap. Aparatus utama: Cards and Counters (kartu angka dan benda hitung). Tanda siap masuk: Anak lulus kotak gelondong dan mengenal kartu 1 sampai 10. Tanda siap lanjut: Anak menyusun seluruh pasangan dengan benar dan menjelaskan ganjil genap dari pasangannya. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 119, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('cd8c44cf-7631-492f-b7c1-bfef8bc83d1d', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Berhitung — Tangga Manik Pendek (Short Bead Stair)', 'Fokus: Jumlah sebagai batang manik berwarna; jembatan ke rantai manik. Aparatus utama: Short Bead Stair (tangga manik pendek). Tanda siap masuk: Anak mantap pada batang bilangan dan kartu dan benda hitung. Tanda siap lanjut: Anak mengenal jumlah dari warna maniknya tanpa menghitung dan menyusun tangga mandiri. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 120, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('b3605fa8-2ccf-4973-a56c-2e0c846ff802', '6d78b895-c2c6-407b-af15-7ba866bf93c7', 'Berhitung — Papan Belasan (Teen Boards)', 'Fokus: Bilangan 11 sampai 19 sebagai sepuluh ditambah satuan. Aparatus utama: Teen Boards (papan belasan), batang manik sepuluh dan satuan. Tanda siap masuk: Anak memahami sepuluh sebagai satu kesatuan dan mantap pada simbol 1 sampai 9. Tanda siap lanjut: Anak membentuk dan membaca 11 sampai 19 dari manik dan dari lambang. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 121, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('5b215833-5a74-4907-b8c5-bd5f8ba24ee1', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Berhitung — Manik Emas & Permainan Bank (Golden Beads)', 'Fokus: Sistem desimal dan operasi konkret: tambah, kurang, kali, bagi. Aparatus utama: Golden Beads (manik emas), kartu angka besar, permainan bank. Tanda siap masuk: Anak mantap pada jumlah dan simbol sampai 19 serta memahami sepuluh sebagai kesatuan. Tanda siap lanjut: Anak mengoperasikan jumlah sampai ribuan secara konkret dengan penukaran benar dan mulai mencatat dengan simbol. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 122, TRUE);
INSERT INTO calistung_materi (id, tahap_id, nama, keterangan, urutan, aktif) VALUES ('793a9f81-78c6-4ac1-9be8-39c8f2098096', 'fec9dc67-c039-4810-bfc8-79bf982b5f78', 'Berhitung — Rantai Manik & Pengukuran', 'Fokus: Menghitung lompat dan memakai bilangan dalam kehidupan. Aparatus utama: Rantai manik pendek, penggaris, timbangan sederhana, gelas ukur. Tanda siap masuk: Anak mantap mengurutkan bilangan dan manik emas berjalan. Tanda siap lanjut: Anak menghitung lompat 2, 5, 10 dengan benar dan mengukur benda nyata secara mandiri. (Materi & Program Pembelajaran Calistung Aparatus Montessori, Bagian 2.)', 123, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('2d8c15e3-36a9-4f01-ba87-61d18ee58bd4', 'Pekan 1 — Kenal Area, Berani Memegang', 'Kuartal 1 · Bulan 1 — Genggam, Gantung & Kuat. Struktur dilatih: S5, S9, S7. Boulder: Eksplorasi pegangan: memanjat bidang miring & dinding sangat rendah, mengenal warna pegangan. Mini Gym: Bar rendah: gantung dibantu; terowongan merangkak. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 1, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('7e81c794-850d-4efa-b33f-cfd345d7c649', 'Pekan 2 — Jalan Beruang & Merangkak Kuat', 'Kuartal 1 · Bulan 1 — Genggam, Gantung & Kuat. Struktur dilatih: S3, S5, S1. Boulder: Traverse sangat rendah mengikuti titik warna besar. Mini Gym: Jalan beruang & merangkak pola silang menyusuri jalur. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 2, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('a6efa13f-2aee-401b-a783-9e22d2a44be7', 'Pekan 3 — Gantung Lebih Lama', 'Kuartal 1 · Bulan 1 — Genggam, Gantung & Kuat. Struktur dilatih: S5, S9. Boulder: Gantung pada pegangan dinding & bar dekat dinding (dihitung bersama). Mini Gym: Gantung–ayun bar rendah; chin hold awal dibantu. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 3, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('aa5830ee-229d-4904-9095-b9be34b66151', 'Pekan 4 — Dorong, Tarik, Angkat', 'Kuartal 1 · Bulan 1 — Genggam, Gantung & Kuat. Struktur dilatih: S5, S3. Boulder: Memanjat sambil mengantar beanbag kecil ke keranjang di titik aman. Mini Gym: Dorong dinding/gerobak beban; tarik tali berpasangan aman. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 4, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('137d3caa-4709-4e28-9307-7d18ec93c503', 'Pekan 5 — Balok Pertamaku', 'Kuartal 1 · Bulan 2 — Seimbang, Lompat & Mendarat. Struktur dilatih: S2, S9. Boulder: Traverse dengan pijakan lebar & rendah. Mini Gym: Balok rendah: berjalan, berhenti, mulai berputar. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 5, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('62eaa11b-4e28-438e-b1c8-6c42c991825a', 'Pekan 6 — Lompat & Menempel (Stick Landing)', 'Kuartal 1 · Bulan 2 — Seimbang, Lompat & Mendarat. Struktur dilatih: S1, S2. Boulder: Lompat turun kecil dari pijakan rendah ke matras, mendarat menempel. Mini Gym: Lompat dua kaki di tempat & ke depan; stick landing 2 detik. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 6, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('7a1b657c-9d92-4607-9b5d-71c8bd5d0f0e', 'Pekan 7 — Berguling Aman', 'Kuartal 1 · Bulan 2 — Seimbang, Lompat & Mendarat. Struktur dilatih: S7, S9. Boulder: Rute rendah setelah guling: transisi lantai ke dinding. Mini Gym: Guling depan dengan bantuan, menuju mandiri bertahap. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 7, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('96690091-6c3c-4126-9d40-9d6a50d41024', 'Pekan 8 — Lompat Turun Bertahap', 'Kuartal 1 · Bulan 2 — Seimbang, Lompat & Mendarat. Struktur dilatih: S1, S2, S10. Boulder: Down-climb lalu lompat turun terpilih dari ketinggian lutut anak. Mini Gym: Lompat turun bertahap (anak tangga ketinggian) & mendarat seimbang. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 8, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('f5c8d9a6-a291-4fd6-9699-ef419fb4f4bf', 'Pekan 9 — Rute Satu Warna', 'Kuartal 1 · Bulan 3 — Rute, Rangkaian & Berani. Struktur dilatih: S9, S8. Boulder: Traverse mengikuti pegangan satu warna. Mini Gym: Rangkaian balok + lompat sederhana. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 9, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('9b6bd631-4526-4dcf-8963-966139bfbbfa', 'Pekan 10 — Naik & Turun Lagi (Down-Climb)', 'Kuartal 1 · Bulan 3 — Rute, Rangkaian & Berani. Struktur dilatih: S9, S5. Boulder: Rute vertikal rendah, turun dengan memanjat kembali. Mini Gym: Bar: gantung–ayun terkontrol. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 10, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('554eda59-19fa-49e6-bd39-2c2bf9847459', 'Pekan 11 — Sirkuit Ceritaku', 'Kuartal 1 · Bulan 3 — Rute, Rangkaian & Berani. Struktur dilatih: S8, S1. Boulder: Stasiun boulder mini di dalam sirkuit 3–4 stasiun. Mini Gym: Stasiun gym mini di dalam sirkuit yang sama. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 11, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('ce98fb73-72a9-4236-8ea8-b7f49a304ad7', 'Pekan 12 — Unjuk Kemampuan Kuartal 1', 'Kuartal 1 · Bulan 3 — Rute, Rangkaian & Berani. Struktur dilatih: Review semua struktur. Boulder: Anak menunjukkan skill boulder pilihannya; peninjauan indikator. Mini Gym: Anak menunjukkan skill gym pilihannya; peninjauan indikator. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 12, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('005610fa-3f2e-4ffb-948b-cc4ac330c442', 'Pekan 13 — Core yang Bangun', 'Kuartal 2 · Bulan 4 — Tubuh Kuat & Terkendali. Struktur dilatih: S5, S2. Boulder: Traverse dengan jeda menahan posisi (pause) di tengah. Mini Gym: Plank anak & dead-bug anak bergiliran; superman menahan. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 13, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('aca73673-41f8-44f1-a7a4-afc6d152a502', 'Pekan 14 — Bahu & Lengan Kuat', 'Kuartal 2 · Bulan 4 — Tubuh Kuat & Terkendali. Struktur dilatih: S5, S9. Boulder: Rute dengan pegangan sedikit lebih kecil (bertahap, sesuai level). Mini Gym: Gantung aktif (mengangkat bahu); wall walk pendek dengan spotting. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 14, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('1458624a-666c-41aa-af93-298b01408c86', 'Pekan 15 — Kaki Kuat', 'Kuartal 2 · Bulan 4 — Tubuh Kuat & Terkendali. Struktur dilatih: S5, S1. Boulder: Teknik menapak & menukar kaki di dinding rendah. Mini Gym: Squat anak, wall sit sebentar, lompat ke kotak rendah. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 15, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('5c7ede53-aa3a-4aa1-8d9a-f63f9a31e589', 'Pekan 16 — Kuat Sambil Bergerak', 'Kuartal 2 · Bulan 4 — Tubuh Kuat & Terkendali. Struktur dilatih: S5, S8. Boulder: Traverse rute mudah tanpa berhenti lama. Mini Gym: Sirkuit kekuatan bergerak: gantung–squat–dorong–plank. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 16, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('d9dc39e3-919d-4651-9db5-cf6710a4732d', 'Pekan 17 — Tangga Ketangkasan Dasar', 'Kuartal 2 · Bulan 5 — Cepat, Tepat & Tangkas. Struktur dilatih: S10, S3. Boulder: Traverse cepat-terkontrol pada rute mudah. Mini Gym: Tangga ketangkasan dua kaki tiap kotak (fokus utama pekan ini). Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 17, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('4bfbf0d5-cfaf-456e-9d27-5d0da4526eb4', 'Pekan 18 — Kaki Cepat, Kaki Tepat', 'Kuartal 2 · Bulan 5 — Cepat, Tepat & Tangkas. Struktur dilatih: S10, S9. Boulder: Menukar kaki (foot swap) di dinding rendah. Mini Gym: Ladder: satu kaki tiap kotak & menyamping. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 18, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('85997cc5-ad0e-458e-8f7d-15e8ff8a3001', 'Pekan 19 — Berhenti – Putar – Lari Lagi', 'Kuartal 2 · Bulan 5 — Cepat, Tepat & Tangkas. Struktur dilatih: S10, S1. Boulder: Berhenti di titik warna dinding saat isyarat. Mini Gym: Slalom cone + start–stop–putar dari isyarat suara. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 19, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('6307b4d7-53aa-4064-968d-9496b707f877', 'Pekan 20 — Reaksi Warna', 'Kuartal 2 · Bulan 5 — Cepat, Tepat & Tangkas. Struktur dilatih: S10, S8. Boulder: Sentuh pegangan warna yang disebut pelatih. Mini Gym: Permainan reaksi warna sambil bergerak di area gym. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 20, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('a17376b1-c8a7-4f35-bfd1-c7e8faaac33f', 'Pekan 21 — Guling Beragam', 'Kuartal 2 · Bulan 6 — Rangkaian Gymnastic. Struktur dilatih: S7, S9. Boulder: Traverse pemanasan ringan. Mini Gym: Guling depan variasi: kaki rapat, kaki lebar, guling ke berdiri. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 21, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('ec856722-ea76-4613-b353-c77d32842cd6', 'Pekan 22 — Balok Berani', 'Kuartal 2 · Bulan 6 — Rangkaian Gymnastic. Struktur dilatih: S2, S9. Boulder: Traverse satu warna lebih jauh. Mini Gym: Balok: jinjit, berputar penuh, lompat turun kecil dari balok. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 22, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('46370bc5-004e-40db-90b3-90486143dfac', 'Pekan 23 — Bar Lanjutan', 'Kuartal 2 · Bulan 6 — Rangkaian Gymnastic. Struktur dilatih: S5, S9. Boulder: Gantung lebih lama di dinding sebagai pendukung. Mini Gym: Chin hold lebih lama; pull-over dibantu spotting; ayun & lepas aman. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 23, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('26ed1dad-305b-4c78-895a-ab379f88906d', 'Pekan 24 — Rangkaian Lantaiku', 'Kuartal 2 · Bulan 6 — Rangkaian Gymnastic. Struktur dilatih: S8, S9. Boulder: Anak memilih satu rute penutup kuartal. Mini Gym: Rangkaian lantai 3–4 elemen pilihan anak; unjuk tengah tahun mini. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 24, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('ddc32247-091b-44ef-8d81-8c7e1cc69439', 'Pekan 25 — Mata Dulu, Tangan Kemudian', 'Kuartal 3 · Bulan 7 — Membaca Rute. Struktur dilatih: S8, S9. Boulder: Membaca rute: menunjuk urutan pegangan dari bawah sebelum memanjat. Mini Gym: Balok & bar sebagai selingan penyeimbang. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 25, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('efb09869-48c7-4758-8929-b32a8ae5c27a', 'Pekan 26 — Rute Pendekku', 'Kuartal 3 · Bulan 7 — Membaca Rute. Struktur dilatih: S9, S8. Boulder: Menyelesaikan rute 4–6 gerakan yang dirancang pelatih. Mini Gym: Guling + lompat rangkaian pendek. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 26, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('47d3a03a-127c-4cd3-b94b-15438b0fef02', 'Pekan 27 — Dua Cara Menyelesaikan', 'Kuartal 3 · Bulan 7 — Membaca Rute. Struktur dilatih: S8, S10. Boulder: Satu rute, dua solusi gerak berbeda. Mini Gym: Sirkuit pilihan: dua jalur berbeda menuju titik akhir. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 27, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('62e8665e-e001-4c5a-aaf5-561f752480b7', 'Pekan 28 — Rute Teman', 'Kuartal 3 · Bulan 7 — Membaca Rute. Struktur dilatih: S8, S9, Regulasi. Boulder: Mencoba rute pilihan teman (didampingi, rute level aman). Mini Gym: Menjadi penjaga titik tunggu & model antre yang baik. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 28, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('d24a7b8b-cf45-4cb6-bd4f-1b234bc945fc', 'Pekan 29 — Dari Lantai ke Dinding', 'Kuartal 3 · Bulan 8 — Kombinasi & Transisi. Struktur dilatih: S8, S7. Boulder: Guling di matras lalu langsung traverse (transisi). Mini Gym: Guling sebagai stasiun awal sirkuit gabungan. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 29, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('a96df2f7-89a3-4860-b26d-957b78758bd3', 'Pekan 30 — Dari Dinding ke Balok', 'Kuartal 3 · Bulan 8 — Kombinasi & Transisi. Struktur dilatih: S8, S2. Boulder: Down-climb lalu berjalan balok tanpa jeda panjang. Mini Gym: Balok sebagai stasiun akhir sirkuit gabungan. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 30, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('4ab31db6-07dd-4786-9ce7-c8cd58d3839c', 'Pekan 31 — Sirkuit Panjang', 'Kuartal 3 · Bulan 8 — Kombinasi & Transisi. Struktur dilatih: S8, S5. Boulder: Stasiun boulder di sirkuit 5–6 stasiun. Mini Gym: Stasiun bar & balok di sirkuit yang sama. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 31, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('2231dd22-5b20-4f38-8772-1f53d088fb4d', 'Pekan 32 — Menyelesaikan dengan Usaha Terbaik', 'Kuartal 3 · Bulan 8 — Kombinasi & Transisi. Struktur dilatih: S8, S10, Regulasi. Boulder: Rute tantangan pilihan (satu tingkat di atas nyaman). Mini Gym: Sirkuit dengan target usaha pribadi, bukan lomba. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 32, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('63bda3f0-2147-4572-80a2-c82ee8deab70', 'Bank A1 — Agility', 'Tangga ketangkasan: dua kaki tiap kotak, maju pelan menuju cepat. Dipakai bergiliran mengikuti nomor pekan (Bank Pemanasan & Agility, Peta Materi Setahun Kelas Movement).', 100, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('28aa6791-bcea-425c-b5ab-be52dc1657d9', 'Pekan 33 — Aku Mau Bisa…', 'Kuartal 3 · Bulan 9 — Target Pribadiku. Struktur dilatih: S8 + target anak. Boulder: Anak memilih satu skill target kuartalnya; baseline ulang struktur prioritasnya. Mini Gym: Penilaian ulang struktur prioritas (Formulir A). Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 33, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('a05c5b17-9cb0-40ab-a978-52e0485167e8', 'Pekan 34 — Latihan Terarah 1', 'Kuartal 3 · Bulan 9 — Target Pribadiku. Struktur dilatih: Sesuai IDP Gerak. Boulder: Latihan fokus pada skill target + pendukung kekuatannya. Mini Gym: Stasiun pendukung sesuai target anak. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 34, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('9403da3c-b720-4fcb-85fe-20af2a0fa79c', 'Pekan 35 — Latihan Terarah 2', 'Kuartal 3 · Bulan 9 — Target Pribadiku. Struktur dilatih: Sesuai IDP Gerak. Boulder: Skill target dimasukkan ke dalam rangkaian/rute. Mini Gym: Skill target dimasukkan ke rangkaian gym. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 35, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('9781531c-21e6-4de4-bf8a-e0ec81b13196', 'Pekan 36 — Cek Target & Unjuk Kuartal 3', 'Kuartal 3 · Bulan 9 — Target Pribadiku. Struktur dilatih: Review semua struktur. Boulder: Anak menunjukkan capaian targetnya; peninjauan indikator. Mini Gym: Anak menunjukkan capaian targetnya; peninjauan indikator. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 36, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('c8ed949b-bb7e-49a9-bb9e-eab302928e4f', 'Pekan 37 — Skill yang Hampir Bisa', 'Kuartal 4 · Bulan 10 — Mengulang dengan Lebih Baik. Struktur dilatih: Sesuai IDP Gerak. Boulder: Stasiun personal: pengulangan struktur terlemah tiap anak. Mini Gym: Stasiun personal bergantian dengan pendamping. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 37, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('1a214976-d5bd-4550-9dff-fc540d869bc0', 'Pekan 38 — Sedikit Lebih Sulit', 'Kuartal 4 · Bulan 10 — Mengulang dengan Lebih Baik. Struktur dilatih: Sesuai IDP Gerak. Boulder: Tantangan naik satu tingkat dari capaian anak. Mini Gym: Tantangan naik satu tingkat (jarak/waktu/variasi). Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 38, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('d964b05c-c8de-4648-a326-711681b40126', 'Pekan 39 — Sedikit Lebih Mandiri', 'Kuartal 4 · Bulan 10 — Mengulang dengan Lebih Baik. Struktur dilatih: Sesuai IDP Gerak. Boulder: Bantuan dikurangi bertahap (isyarat menuju mandiri). Mini Gym: Bantuan dikurangi bertahap; anak memimpin pemanasannya sendiri sebagian. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 39, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('97f58bac-86ee-4512-8703-ff72d8dbda9f', 'Pekan 40 — Konsisten Itu Keren', 'Kuartal 4 · Bulan 10 — Mengulang dengan Lebih Baik. Struktur dilatih: Sesuai IDP Gerak. Boulder: Pengulangan rute andalan sampai tampil konsisten. Mini Gym: Pengulangan rangkaian andalan sampai konsisten. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 40, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('c0df0d5a-a304-4ced-b8e6-f0036af6b544', 'Pekan 41 — Berpasangan Bergerak', 'Kuartal 4 · Bulan 11 — Bersama & Memimpin. Struktur dilatih: S3, S8. Boulder: Traverse bergantian saling menunggu & memberi contoh. Mini Gym: Gerak cermin (mirror movement) & sirkuit berpasangan. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 41, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('ccf098b6-9b60-42c3-bb1b-0551de173f9a', 'Pekan 42 — Aku Jadi Contoh', 'Kuartal 4 · Bulan 11 — Bersama & Memimpin. Struktur dilatih: S9, Regulasi. Boulder: Anak Level Siap menjadi model stasiun boulder. Mini Gym: Anak Level Siap menjadi model stasiun gym. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 42, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('35196f3b-74ab-48e7-8896-dc55caa7f6f0', 'Pekan 43 — Rute untuk Teman', 'Kuartal 4 · Bulan 11 — Bersama & Memimpin. Struktur dilatih: S8, S9. Boulder: Anak merancang rute mudah untuk temannya. Mini Gym: Anak menyusun satu stasiun gym untuk temannya. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 43, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('9091b8c6-b290-4245-8c03-4402d60298b2', 'Pekan 44 — Tim Menyelesaikan Misi', 'Kuartal 4 · Bulan 11 — Bersama & Memimpin. Struktur dilatih: S8, S5. Boulder: Misi boulder kelompok: semua anak menyelesaikan rute tim. Mini Gym: Misi sirkuit kelompok dengan peran bergantian. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 44, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('edfeb46c-835e-4d4f-806e-2d8672aa0427', 'Pekan 45 — Persiapan Festival 1', 'Kuartal 4 · Bulan 12 — Festival Gerak. Struktur dilatih: Pilihan anak. Boulder: Memilih & memoles skill boulder andalan. Mini Gym: Memilih & memoles skill gym andalan. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 45, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('adf8d334-213d-4c8e-aef4-21e30ac07f8f', 'Pekan 46 — Persiapan Festival 2', 'Kuartal 4 · Bulan 12 — Festival Gerak. Struktur dilatih: S8. Boulder: Rangkaian pertunjukan boulder (rute andalan + transisi). Mini Gym: Rangkaian pertunjukan gym (3–4 elemen). Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 46, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('3064ee50-4719-4b45-97db-4969fed55971', 'Pekan 47 — Gladi & Portofolio', 'Kuartal 4 · Bulan 12 — Festival Gerak. Struktur dilatih: S8. Boulder: Gladi rute pertunjukan; dokumentasi portofolio gerak (dengan persetujuan orang tua). Mini Gym: Gladi rangkaian; dokumentasi portofolio gerak. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 47, TRUE);
INSERT INTO movement_materi (id, judul, keterangan, urutan, aktif) VALUES ('96b2e07e-265a-407f-ac4f-6fdc57ea5b86', 'Pekan 48 — Festival Gerak & Review Tahunan', 'Kuartal 4 · Bulan 12 — Festival Gerak. Struktur dilatih: Review tahunan semua struktur. Boulder: Festival: anak tampil untuk orang tua; penilaian akhir tahun semua struktur & keputusan level berikutnya. Mini Gym: Festival: anak tampil untuk orang tua; penilaian akhir tahun semua struktur & keputusan level berikutnya. Pemanasan, sirkuit (heavy work), dan pendinginan mengikuti Bank yang berputar sesuai nomor pekan; setiap pekan dua sesi: Sesi A perkenalan & teknik, Sesi B pendalaman & rangkaian.', 48, TRUE);
