INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('83760df4-d2c2-4471-b48c-9f867369d4df', 'Dampak Kesulitan Belajar', 'Sosial-emosi', 'Tanda yang terlihat: Cemas & menangis menjelang sekolah/ulangan; sakit perut/kepala tanpa sebab medis jelas; ledakan emosi sepulang sekolah
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('3f7e4da5-22a6-4fcb-84ca-b8250da1a634', 'Dampak Kesulitan Belajar', 'Konsep diri akademik', 'Tanda yang terlihat: Mengatakan dirinya bodoh; menolak mencoba sebelum mulai; membandingkan diri dengan adik/teman
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('766b5dee-4976-43fe-bb66-ff755c9c64d8', 'Dampak Kesulitan Belajar', 'Perilaku di kelas', 'Tanda yang terlihat: Menghindari tugas (ke toilet, mengobrol, melamun), menjadi badut kelas, atau menentang guru
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('a579c2b7-b97e-4bca-833e-63b3e66e70d5', 'Dampak Kesulitan Belajar', 'Sosial & pertemanan', 'Tanda yang terlihat: Menarik diri atau dipilih terakhir dalam kelompok; diejek karena membaca/menulisnya
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('fd6c2e97-5d03-4766-9e8c-ca44a7c04f3a', 'Dampak Kesulitan Belajar', 'Kemandirian & kebiasaan belajar', 'Tanda yang terlihat: Belajar selalu harus ditemani; tidak punya strategi saat tidak paham; menyerah pada soal pertama yang sulit
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('6b1dc6cd-ff41-4682-94b5-33cbc0fb8b00', 'Dampak Kesulitan Belajar', 'Relasi keluarga', 'Tanda yang terlihat: PR menjadi konflik malam hari; orang tua dianggap kurang mendampingi; saudara dibandingkan
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('b89c148e-198b-4410-9ad0-7dcfd1fc4ebb', 'Dampak Kesulitan Belajar', 'Jangka panjang (bila tak didukung)', 'Tanda yang terlihat: Kesenjangan melebar (efek Matius: yang lancar makin banyak membaca, yang sulit makin tertinggal), menghindari jalur pendidikan berbasis teks, pilihan masa depan menyempit
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('094f04f6-f7e7-4edd-ae00-0cb6da3c4eaf', 'Pemetaan Kekuatan (MIND)', 'Material (ruang & benda)', 'Kuat membayangkan benda 3D, jago merakit/memperbaiki/menggambar ruang, memahami mesin atau konstruksi secara intuitif', 137, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('4222bfaa-7af2-4aca-b82d-eb6d9d4ea677', 'Pemetaan Kekuatan (MIND)', 'Interconnected (keterhubungan)', 'Melihat gambaran besar & pola lintas topik, menghubungkan ide yang bagi orang lain tampak terpisah, berpikir sistem', 138, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('7ed4e30f-b12b-455f-8236-c1423a090fab', 'Pemetaan Kekuatan (MIND)', 'Narrative (naratif)', 'Kuat bercerita & memahami manusia lewat cerita, ingatan kuat pada pengalaman & peristiwa (bukan pada teks), pandai membaca situasi sosial', 139, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('52680968-f5f6-4ca2-a5e5-64d9de1d23af', 'Pemetaan Kekuatan (MIND)', 'Dynamic (dinamis)', 'Belajar paling cepat dari praktik & pengalaman langsung, berani mencoba, menemukan cara sendiri di luar prosedur baku', 140, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('e0d0db6b-7f41-47e4-8122-2c52438fc9e8', 'Skrining Risiko Disleksia', 'Batas Penamaan & Kewenangan', 'Di dalam sistem lembaga, seluruh alat dari folder pemilik masuk dengan nama dan fungsi Skrining dan Identifikasi Risiko Disleksia. Tidak ada satu pun alat yang berfungsi menegakkan diagnosis — diagnosis tetap ranah psikolog klinis. Setiap laporan hasil skrining bermuara pada dua hal saja: rekomendasi dukungan belajar berdasarkan kebutuhan yang teramati, dan pilihan rujukan kepada psikolog klinis bila terindikasi. Bahasa laporan adalah hasil pemetaan dan kebutuhan dukungan anak, bukan label. Bank tugas ini melengkapi Layanan Skrining sebagai bank tugas per usia dan jenjang, bukan sumber kebenaran kedua: katalog skrining kesulitan belajar 100 indikator dan panduan red flag 12 kelompok indikasi tetap menjadi daftar amati utama.', 141, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('0fb0b95c-8d6d-4a25-9963-4c6a7cdeb5ba', 'Skrining Risiko Disleksia', 'Perangkat Gerakan Bhinneka — 7 Aspek & Kaidah Baca', 'Tabel hasil per aspek (jumlah pertanyaan): Bicara dan Bahasa (5), Kesadaran Fonologis (7), Membaca (12), Mengeja dan Menulis (12), Memori dan Pemrosesan Auditori (7), Perilaku Belajar (7), Organisasi, Perilaku, dan Emosi (6) — seluruhnya 56 pertanyaan. Kaidah baca: ada kesulitan pada satu aspek bila lebih dari separuh pertanyaannya dijawab YA; tiga pertanyaan penanda khusus ditandai warna abu-abu. Kalimat penutup laporan: hasil skrining belum dapat digunakan untuk menegakkan diagnosis dan perlu asesmen psikologis dan edukatif yang lebih mendalam.', 142, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('ba68d290-095a-4ad5-aaf5-bb883a8d8bae', 'Skrining Risiko Disleksia', 'Bank Tugas TK Akhir – SD Awal (5–9 th): Kesadaran Fonologis', 'Subtest Kesadaran Rima — 10 soal gambar (dari rima dan onset.pdf): anak menunjuk gambar yang bunyi akhirnya sama dengan gambar soal. Subtest Kesadaran Bunyi Awal — 10 soal gambar: anak menyebut bunyi awal kata dan mencari gambar berbunyi awal sama. Tugas rima lisan, bunyi awal, segmentasi kata, dan penggabungan bunyi (dari Screening Disleksia.docx) sebagai tugas lisan pendamping, dengan kata contoh dari berkas aslinya. Tugas hubungan huruf dan bunyi serta pengamatan minat dan fokus saat belajar fonik dicatat sebagai pengamatan, bukan skor. Catatan berkas: folder hanya memuat Subtest 2 dan Subtest 4 dari baterai kesadaran fonologisnya; subtest lain tidak dikarang dan tidak dilengkapi dari sumber lain.', 143, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('60dc1799-8ab5-4edb-8cdd-09d121a129bf', 'Skrining Risiko Disleksia', 'Bank Tugas SD (Kelas 1–6): Protokol Kegiatan Membaca', 'Bahan bacaan sesuai usia atau kemampuan anak (tanpa gambar dan dengan gambar), tanpa pencatatan waktu, observasi perilaku membaca selama anak membaca, lalu pengisian indikator Ya atau Tidak per aspek mengikuti perangkat Gerakan Bhinneka. Persiapan: ruang tenang, duduk berhadapan, tidak buru-buru membantu, bantuan dicatat sebagai kesalahan. Daftar sumber bahan bacaan gratis resmi dipakai sebagai bank bahan bacaan skrining lembaga: Pusat Pembinaan Bahasa dan Sastra, Pusat Perbukuan Kemendikbud, Literacy Cloud, Let''s Read, Platform Merdeka Mengajar.', 144, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('adcbc51a-b4b1-44df-8e28-623608b851c0', 'Skrining Risiko Disleksia', 'Bank Asupan Remaja (SMP–SMA): Anamnesis & Fungsi Eksekutif', 'Struktur lembar biodata dan anamnesis remaja (dari LK & Skrining Disleksia Remaja.pdf) dipakai sebagai formulir asupan jenjang remaja, menyatu dengan wawancara anamnesis W5 agar tidak ada dua versi anamnesis: identitas anak dan keluarga, riwayat pendidikan, tujuan pemeriksaan, permasalahan saat ini, usaha yang sudah dilakukan, riwayat kehamilan dan kelahiran, riwayat perkembangan, dan kondisi anak saat ini. Kelompok butir fungsi eksekutif dari berkas yang sama — Working Memory, Task Initiation, Planning and Organization, Inhibitory Control, dan Flexibility — dipakai sebagai bahan wawancara dan observasi pendukung pemetaan kekuatan MIND pada perpanjangan remaja.', 145, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('00e37ca3-ce3f-4024-8915-f4c7f0813c87', 'Skrining Risiko Disleksia', 'Bahan Pendukung Lintas Jenjang', 'Tahapan Perkembangan Bahasa Normal dipakai sebagai lampiran acuan wawancara skrining bicara dan bahasa untuk jenjang TK dan SD awal. Butir riwayat keluarga (riwayat disleksia pada keluarga dekat) dan butir lain dari SD_Dyslexia indicators.pdf yang belum tercakup katalog 100 indikator diambil sebagai pelengkap daftar wawancara guru dan orang tua. Delapan video folder pemilik dipakai sebagai bank media pelatihan pemeriksa internal, bukan bagian dari instrumen dan tidak ditampilkan sebagai hasil skrining.', 146, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('1c038578-a2b5-4f38-82d6-ccd5cc24d7c4', 'Skrining Risiko Disleksia', 'Format Laporan Hasil Skrining Risiko Disleksia (Diadopsi)', '1) Identitas anak dan keterangan orang tua, termasuk riwayat keluarga dan keluhan utama. 2) Tabel hasil per aspek berisi jumlah pertanyaan, jumlah kesulitan yang teramati, dan keterangan — mengikuti tujuh aspek perangkat Gerakan Bhinneka untuk jenjang SD, dan tabel per ranah untuk jenjang lain mengikuti katalog lembaga. 3) Ringkasan gambaran anak dalam narasi. 4) Kesimpulan dalam bahasa pemetaan non diagnostik, memuat kalimat batas bahwa hasil skrining tidak menegakkan diagnosis. 5) Rekomendasi dukungan belajar di sekolah dan di rumah, serta pilihan rujukan ke psikolog klinis bila terindikasi, dengan kolom tujuan rujukan yang diketik saat penerbitan mengikuti kaidah berkas rujukan lembaga. 6) Sesi penjelasan hasil kepada orang tua sebagai penutup alur, dan pengiriman laporan sebagai berkas ke WhatsApp atau email orang tua dengan pencatatan pengiriman, mengikuti aturan klien bukan anggota.', 147, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('6008e794-ed7f-4598-88d9-a25678930b59', 'Skrining Risiko Disleksia', 'Yang Ditolak dari Folder Pemilik (dan Alasannya)', '1) Norma ORF Hasbrouck & Tindal 2017 sebagai acuan skor — DITOLAK: norma kecepatan membaca teks bahasa Inggris anak sekolah Amerika; protokol lembaga sendiri dengan sengaja tidak mencatat waktu. Berkasnya disimpan sebagai literatur latar saja. 2) Daftar Target Ladders Dyslexia sebagai instrumen tersendiri — DITOLAK sebagai instrumen kedua (tumpang tindih besar dengan katalog 100 indikator; hanya butir yang belum tercakup yang diambil sebagai pelengkap wawancara; catatan hak cipta berkasnya juga tidak mendukung adopsi utuh). 3) Anjuran memperlakukan anak sebagai anak disleksia sampai terbukti bukan — DITOLAK: dukungan diberikan berdasarkan kebutuhan yang teramati tanpa melekatkan label. 4) Penamaan alat sebagai alat diagnosis — DITOLAK di seluruh permukaan sistem, dokumen, dan laporan. 5) Subtest fonologi di luar yang tersedia — tidak dikarang.', 148, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('f33136a7-73a2-4438-8826-de587fedc902', 'Kurasi Folder Bakat Minat', 'Temuan Folder: Bukan Materi Bakat Minat', 'Seluruh isi folder Drive ''Bakat Minat'' adalah satu paket produk komersial pelatihan terapis dari psikologisehat.id (11 berkas PDF, 1.556 halaman). Tidak ada satu pun materi Talents Mapping atau instrumen pemetaan bakat di dalamnya, dan tidak ada tes psikologi formal. Karena paket ini produk komersial pihak ketiga, teksnya tidak boleh disalin ke dokumen lembaga (hak cipta dan merek); yang diambil hanyalah pengetahuan yang disuling dan ditulis ulang dengan bahasa lembaga sendiri. Nilai pakainya ada di dua pinggiran: keterampilan percakapan konsultasi dan literasi indikasi untuk rujukan. Kebutuhan inti layanan Bakat Minat (perangkat observasi kekuatan, panduan wawancara penelusuran minat, format riwayat aktivitas, format peta kekuatan) tetap disusun dari perangkat lembaga sendiri.', 149, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('0f623751-aefc-43b4-988b-8e0fe695fff1', 'Indikator Usia Sekolah', 'Menulis · SMP (12-15 th)', 'Esai/karangan terstruktur (pendahuluan-isi-penutup) belum terbentuk', 57, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('ccff9058-3ea7-4c64-b7e5-3c8ab757cb15', 'Indikator Usia Sekolah', 'Menulis · SMP (12-15 th)', 'Menyalin jawaban tanpa memahami karena menulis adalah beban tersendiri', 58, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('902cf22f-83e1-4e8e-9571-bd01f3f1de7f', 'Kurasi Folder Bakat Minat', 'AMBIL: Kerangka Tahap Perkembangan (Latar Konsultasi)', 'Tabel stresor dan kekuatan spesifik tiap tahap perkembangan serta strategi komunikasi berdasarkan usia (dari Panduan Konseling Sesuai Umur) dipakai sebagai lensa membaca saat wawancara penelusuran minat dan penyusunan peta kekuatan anak dan remaja — rentang 6–12 dan 12–18 paling relevan berdampingan katalog usia sekolah. Posisinya pengetahuan pendamping sesi konsultasi, bukan instrumen asesmen baru, supaya tidak lahir sumber kebenaran kedua di samping perangkat lembaga.', 150, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('0d17c389-862e-4497-9d4b-934a4b09e3b4', 'Kurasi Folder Bakat Minat', 'AMBIL: Pola Pertanyaan Berbasis Kekuatan', 'Keluarga pertanyaan berbasis kekuatan (pertanyaan pengecualian, pertanyaan kompetensi dan pemecahan masalah, eksplorasi kehidupan dan diri) menjadi bahan mentah menyusun daftar pertanyaan wawancara penelusuran minat dan kekuatan milik lembaga sendiri (anak, remaja, dan orang tua). Diambil pola bertanyanya, ditulis ulang, dan dibuang seluruh bingkai terapinya.', 151, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('a1a5fda7-376c-4775-824a-126513f3f25d', 'Kurasi Folder Bakat Minat', 'AMBIL: Keterampilan Dasar Sesi (SOP Konsultasi)', 'Membangun rapport, mendengarkan aktif dan reflektif, bertanya efektif, membuka sesi dengan check-in dan menutup dengan wrap-up, menjelaskan kerahasiaan dan persetujuan di awal, serta mengenali kompetensi dan batasan pemberi layanan yang mempertegas batas non klinis lembaga — dialihkan bahasanya dari ''sesi terapi'' menjadi ''sesi konsultasi dan pemetaan'' dan masuk bahan SOP sesi konsultasi.', 152, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('8b903ccb-6524-4d64-b17e-ef73f157567b', 'Kurasi Folder Bakat Minat', 'BAHAN INDIKASI UNTUK RUJUKAN (Dibaca sebagai Tanda, Bukan Protokol)', 'Tanda-tanda krisis dan risiko tinggi (termasuk pembicaraan tentang bunuh diri), bentuk ucapan dan perilaku yang menjadi objek asesmen ideasi bunuh diri, percobaan bunuh diri, potensi membahayakan orang lain, dan psikosis, serta uraian kesenjangan antar domain dan regresi perkembangan, hidup hanya sebagai lapisan pengenalan tanda bahaya: dikenali, dicatat apa adanya, diteruskan hari yang sama, dan dirujuk atau dieskalasi ke psikiater, psikolog klinis, atau layanan darurat. Protokol bertanyanya TIDAK dijalankan guru dan pendamping — menggali ideasi, rencana, dan psikosis adalah asesmen klinis. Peta modalitas terapi hidup sebatas literasi tujuan rujukan (modalitas apa menangani persoalan apa) agar berkas rujukan dapat menyebut kebutuhan profesional yang tepat.', 153, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('57a5b7bd-aad3-4dcb-8e34-2b7ac3dcfac4', 'Kurasi Folder Bakat Minat', 'TOLAK & TETAP DILARANG', 'Ditolak sebagai perangkat praktik: skrip sesi terapi, skrip CBT, intervensi langkah demi langkah 32 modalitas, metafora dan one liner sebagai teknik, teori modalitas sebagai dasar praktik, treatment plan dan catatan progres klinis sebagai jenis dokumen, serta berkas kode diskon penjual. Tetap dilarang dalam keadaan apa pun: instrumen berlisensi pihak ketiga (Talents Mapping, ST-30, TMA, dan sejenisnya) tanpa lisensi dan sertifikasi praktisi resmi; label diagnosis di permukaan mana pun; klaim konseling klinis dan penanganan — layanan lembaga tetap konsultasi dan pemetaan non klinis dengan pendampingan sebelum dan sesudah rujukan; tes dan asesmen psikologi formal, yang hanya boleh diberikan dan ditafsirkan psikolog berlisensi HIMPSI.', 154, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('d48167ea-7031-4f69-9878-9b5737f0d377', 'Indikator Usia Sekolah', 'Membaca · SD Awal (6-9 th)', 'Sering menukar, menghilangkan, atau menambah huruf/bunyi (b-d, p-q, kata terbalik sebagian)', 27, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('a0749f94-439a-4346-b2f8-120081cc0ce3', 'Indikator Usia Sekolah', 'Membaca · SD Awal (6-9 th)', 'Menebak kata dari gambar/huruf awal dan menolak membaca kata baru', 28, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('b7630817-a37b-41b4-a32e-a7c557590df8', 'Indikator Usia Sekolah', 'Membaca · SD Awal (6-9 th)', 'Menghindari membaca nyaring; lelah sangat cepat saat membaca', 29, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('38afbefe-0c6b-4669-873b-66dbe3189a86', 'Indikator Usia Sekolah', 'Membaca · SD Awal (6-9 th)', 'Memahami cerita yang DIBACAKAN jauh lebih baik daripada yang dibaca sendiri', 30, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('a38aa171-2e84-409d-936d-0b92a88de278', 'Indikator Usia Sekolah', 'Membaca · SD Akhir (9-12 th)', 'Akurasi menurun pada kata panjang/multisuku; melewatkan baris atau kata kecil', 32, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('8421dc44-5158-463f-9d8b-d773878b1885', 'Indikator Usia Sekolah', 'Membaca · SD Akhir (9-12 th)', 'Pemahaman bacaan lemah karena energi habis untuk mengurai kata', 33, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('d40330d1-88cb-400d-8efd-c23bd0c2bde2', 'Indikator Usia Sekolah', 'Membaca · SD Akhir (9-12 th)', 'Ejaan pada tulisan bebas sangat tidak konsisten untuk kata yang sama', 34, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('27cb5bb4-7f0e-401f-aff2-c6eb58e5dec4', 'Indikator Usia Sekolah', 'Membaca · SD Akhir (9-12 th)', 'Menghindari pelajaran yang padat teks; prestasi turun terutama pada mapel berbasis bacaan', 35, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('a465d055-e9cb-45d2-b5d0-46ed173a4676', 'Indikator Usia Sekolah', 'Membaca · SMP (12-15 th)', 'Mengandalkan rangkuman/audio/teman untuk memahami materi tertulis', 37, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('44182cdc-bf63-41cd-a6b8-efbdda8cdf49', 'Indikator Usia Sekolah', 'Membaca · SMP (12-15 th)', 'Kosa kata akademik tertinggal karena jarang membaca tuntas', 38, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('76db2902-18ec-4a0b-8e29-6a24a6fa9220', 'Indikator Usia Sekolah', 'Membaca · SMP (12-15 th)', 'Kesalahan membaca kata istilah (sains, bahasa asing) menetap', 39, TRUE);
INSERT INTO bank_deteksi (id, kategori, judul, isi, urutan, aktif) VALUES ('fb885365-52dc-4aaa-bcdd-2b5f3eaff38e', 'Indikator Usia Sekolah', 'Membaca · SMP (12-15 th)', 'Menolak presentasi/membaca di depan kelas; tampak sebagai sikap, akarnya keterampilan', 40, TRUE);
